global using Xunit;
global using Microsoft.Extensions.AI.Evaluation;
global using Microsoft.Extensions.AI.Evaluation.Quality;
global using Microsoft.Extensions.AI.Evaluation.Reporting;

using System.Text.Json.Serialization;

namespace MyApp.Evals.Tests;

public sealed class EvalScenario
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = string.Empty;

    [JsonPropertyName("user_message")]
    public string UserMessage { get; set; } = string.Empty;

    [JsonPropertyName("expected_traits")]
    public List<string> ExpectedTraits { get; set; } = [];
}

using System.Text.Json;
using Microsoft.Extensions.AI;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> Scenarios =>
        LoadScenarios().Select(s => new object[] { s.Id, s });

    [Theory]
    [MemberData(nameof(Scenarios))]
    public async Task EvaluateScenario(string id, EvalScenario scenario)
    {
        // Arrange
        var rubric = await File.ReadAllTextAsync(RubricPath);
        var chatMessages = new List<ChatMessage>
        {
            new(ChatRole.User, scenario.UserMessage)
        };

        // Act — invoke the agent under test (replace with actual agent call)
        var response = await InvokeAgentAsync(chatMessages);

        // Assert — verify expected traits are present in the response
        Assert.NotNull(response);
        Assert.NotEmpty(response);

        foreach (var trait in scenario.ExpectedTraits)
        {
            Assert.Contains(trait, response, StringComparison.OrdinalIgnoreCase);
        }
    }

    private static async Task<string> InvokeAgentAsync(IList<ChatMessage> messages)
    {
        // TODO: Replace with actual agent invocation against MyApp.AppHost
        await Task.CompletedTask;
        throw new NotImplementedException(
            "Connect this method to your agentic app endpoint. " +
            "For example, use HttpClient to call the AppHost chat endpoint.");
    }

    private static List<EvalScenario> LoadScenarios()
    {
        var json = File.ReadAllText(GoldenPath);
        return JsonSerializer.Deserialize<List<EvalScenario>>(json) ?? [];
    }
}

